package synapse.finance
default allow = false
allow { input.amount <= input.agent.spendCeilingUsd }
requires_approval { input.amount > input.agent.requiresHitlAboveUsd; input.amount <= input.agent.spendCeilingUsd }

package synapse.security
default allow = true
deny { input.session_trajectory[_].tool == "disable_audit"; input.tool == "bulk_delete" }

package synapse.infra
default allow = true
deny { re_match("DROP|TRUNCATE|terminate_all", input.query_or_command) }
